/**
 * A revisão do DNA — a escada de bases, e os degraus que não fecham.
 *
 * A regra de pareamento é fixa: A só com T, C só com G. Quem revisa uma cópia
 * procura o degrau que desobedece. A cena existe porque a lista de letras da
 * interface não mostra o que um degrau errado É — uma ponte que não encaixa; aqui
 * o par certo se fecha no meio da escada, e o errado deixa uma fenda.
 *
 * Marcado pelo usuário ganha anel; só depois de verificar é que o desenho revela
 * quais eram de fato os erros. Antes disso ele não pode entregar a resposta.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Uma cor por base — é por ela que o olho acha o par repetido na escada. */
const CORES_BASE: Readonly<Record<string, string>> = {
  A: '#3c6fd1',
  T: '#d98324',
  C: '#2f8f5c',
  G: '#a4499c',
};

const PAR: Readonly<Record<string, string>> = { A: 'T', T: 'A', C: 'G', G: 'C' };

interface Coluna {
  readonly a: string;
  readonly b: string;
}

function colunasDe(bruto: unknown): Coluna[] {
  if (!Array.isArray(bruto)) return [];

  const lista: Coluna[] = [];
  for (const item of bruto) {
    if (item === null || typeof item !== 'object') continue;
    const { a, b } = item as { a?: unknown; b?: unknown };
    lista.push({ a: typeof a === 'string' ? a : '', b: typeof b === 'string' ? b : '' });
  }
  return lista;
}

function numerosDe(bruto: unknown): number[] {
  return Array.isArray(bruto) ? bruto.map((n) => Number(n)).filter((n) => Number.isFinite(n)) : [];
}

const dna: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Metade de um degrau: o bloco da base, com a letra. */
  function base(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    largura: number,
    altura: number,
    letra: string,
    deCima: boolean,
    apagada: boolean,
  ): void {
    const cor = paleta();
    const tinta = CORES_BASE[letra] ?? cor.fraco;

    ctx.save();
    if (apagada) ctx.globalAlpha = 0.35;

    // O bloco aponta para o meio da escada, onde encontra o par.
    const bico = Math.min(altura * 0.45, largura * 0.5);
    ctx.beginPath();
    if (deCima) {
      ctx.moveTo(x, y);
      ctx.lineTo(x + largura, y);
      ctx.lineTo(x + largura, y + altura - bico);
      ctx.lineTo(x + largura / 2, y + altura);
      ctx.lineTo(x, y + altura - bico);
    } else {
      ctx.moveTo(x, y + altura);
      ctx.lineTo(x + largura, y + altura);
      ctx.lineTo(x + largura, y + bico);
      ctx.lineTo(x + largura / 2, y);
      ctx.lineTo(x, y + bico);
    }
    ctx.closePath();
    ctx.fillStyle = tinta;
    ctx.fill();

    texto(
      ctx,
      letra,
      x + largura / 2,
      y + altura / 2 + (deCima ? -bico * 0.15 : bico * 0.15),
      Math.min(altura * 0.5, largura * 0.7),
      { cor: cor.contraste, peso: 800 },
    );
    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const colunas = colunasDe(estado.colunas);
    const marcados = new Set(numerosDe(estado.selecionados));
    const erros = new Set(numerosDe(info.erros));
    const revelar = estado.resolvido === true;
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A só pareia com T; C só com G');

    if (colunas.length === 0) return;

    const x0 = L * 0.06;
    const x1 = L * 0.94;
    const passo = (x1 - x0) / colunas.length;
    const largura = passo * 0.66;
    const meio = A * 0.52;
    const alturaBase = Math.min(A * 0.15, passo * 1.1);
    const folga = A * 0.012;

    // ── As fitas: duas linhas que ondulam de leve, o esqueleto açúcar-fosfato ──
    for (const [lado, sinal] of [
      ['cima', -1],
      ['baixo', 1],
    ] as const) {
      void lado;
      const y = meio + sinal * (alturaBase + folga + A * 0.055);
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = Math.max(3, A * 0.016);
      ctx.lineCap = 'round';
      ctx.beginPath();
      for (let i = 0; i <= colunas.length * 6; i++) {
        const u = i / (colunas.length * 6);
        const px = x0 + u * (x1 - x0);
        const py = y + Math.sin(u * Math.PI * colunas.length * 0.5) * A * 0.014 * sinal;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
    }

    // ── Os degraus ────────────────────────────────────────────────────────
    const miudo = limitar(A * 0.03, 8, 11);

    for (const [i, coluna] of colunas.entries()) {
      const cx = x0 + passo * (i + 0.5);
      const x = cx - largura / 2;
      const errado = erros.has(i);
      const marcado = marcados.has(i);

      // Antes de verificar, nada denuncia o erro: é o que o puzzle pede achar.
      const apagada = revelar && !errado && marcado;

      base(ctx, x, meio - folga - alturaBase, largura, alturaBase, coluna.a, true, apagada);
      base(ctx, x, meio + folga, largura, alturaBase, coluna.b, false, apagada);

      // A fenda do par que não fecha só aparece depois de verificar.
      if (revelar && errado) {
        ctx.strokeStyle = cor.erro;
        ctx.lineWidth = 2;
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(x - 2, meio);
        ctx.lineTo(x + largura + 2, meio);
        ctx.stroke();
        ctx.setLineDash([]);
        texto(ctx, `≠${PAR[coluna.a] ?? '?'}`, cx, meio + alturaBase * 1.9, miudo, {
          cor: cor.erro,
          peso: 800,
        });
      }

      if (marcado) {
        ctx.strokeStyle = revelar ? (errado ? cor.verde : cor.erro) : cor.azul;
        ctx.lineWidth = 2.4;
        retangulo(
          ctx,
          x - 3,
          meio - folga - alturaBase - 4,
          largura + 6,
          (alturaBase + folga) * 2 + 8,
          6,
          undefined,
          ctx.strokeStyle,
          2.4,
        );
      }

      texto(ctx, `${i + 1}`, cx, meio - alturaBase * 1.9, miudo, {
        cor: cor.fraco,
        peso: 600,
      });
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      `${erros.size} erro(s) de cópia encontrados ✔`,
      marcados.size === 0
        ? 'Toque nos degraus em que as bases não se encaixam.'
        : `${marcados.size} degrau(s) marcado(s) — confira se não sobrou nenhum.`,
    );
  }

  const base2d = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base2d.redimensionar,
    pausar: base2d.pausar,
    retomar: base2d.retomar,
    destruir: base2d.destruir,
  };
};

export default dna;
